133	def selected_ctest(call, output, name, build_dir, allow_gpu=False, prefix=None):
134	    """Discover and save the exact safe selection before the caller executes it."""
135	    require(list(prefix or []) in [[],
136	        ['env', '-u', 'ASAN_OPTIONS', '-u', 'LSAN_OPTIONS', 'UBSAN_OPTIONS=halt_on_error=1'],
137	        ['env', 'ASAN_OPTIONS=detect_leaks=0', 'UBSAN_OPTIONS=halt_on_error=1']], 'unreviewed CTest wrapper')
138	    _, guarded = pre_discovery_gate(build_dir)
139	    # Retain the exact checked identity; the callback may use a different cwd.
140	    build_dir = Path(guarded['build_dir'])
141	    discovery = call(name + '_discovery', ['ctest', '--test-dir', str(build_dir), '-N', '--show-only=json-v1'], 60)
142	    require(discovery.get('exit_code', 0) == 0, 'CTest discovery failed')
143	    plan = select_tests(strict_json(discovery['stdout']), build_dir, allow_gpu)
144	    require(plan['build_metadata'] == guarded, 'build metadata changed during discovery')
145	    dump_new(output / (name + '_selection.json'), plan)
146	    # Repeat source AND generated-metadata checks at the execution boundary.
147	    _, final_guard = pre_discovery_gate(build_dir)
148	    require(final_guard == guarded, 'build metadata changed before execution')
149	    result = call(name, list(prefix or []) + plan['ctest_argv'], 900)
150	    require(re.search(r'0 tests failed out of ' + str(plan['selected_count']) + r'(?:\s|$)', result['stdout']) and
151	            '***Skipped' not in result['stdout'], 'non-timing correctness coverage failed/skipped')
152	    return result
